import logging
import importlib

from browser_use.logging_config import setup_logging

def test_verbose_logging_output():
    # Capture console output
    stream = io.StringIO()
    # Force re‑setup to ensure our custom level is registered
    logger = setup_logging(stream=stream, log_level='verbose', force_setup=True)
    # Use the logger for the main package
    bu_logger = logging.getLogger('browser_use')
    # Emit a VERBOSE message
    bu_logger.verbose('hello verbose')
    output = stream.getvalue()
    # The output should contain the VERBOSE level name and our message
    assert 'VERBOSE' in output
    assert 'hello verbose' in output
    # Clean up handlers to avoid side effects for other tests
    for h in list(bu_logger.handlers):
        bu_logger.removeHandler(h)
    # Reset root logger handlers as well
    root = logging.getLogger()
    for h in list(root.handlers):
        root.removeHandler(h)
